INSERT INTO money_flow VALUES ('Sequoia Capital','Dropbox','資金調達','','2007','$1.2 million','Museの調査: Crucible Moments「Dropbox ft. Drew Houston」回。公式文字起こしで「2007年秋にSequoiaがDropboxのseedラウンドを主導した」と明記。金額はHouston本人のインタビューとseedlist等の資料で確認','https://sequoiacap.com/podcast/crucible-moments-dropbox','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('eBay','PayPal','買収','','2002','$1.5 billion','Museの調査: Crucible Moments「PayPal ft. Max Levchin」回。複数回の買収提案の経緯が語られ、ホストが「今度の提案は$1.5 billionだった」と明言。eBay公式発表（2002年7月発表、同年10月完了）でも一致。それ以前の約$1 billionの提案を断ってIPOした話も','https://sequoiacap.com/podcast/crucible-moments-paypal','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('SoftBank','Supercell','大株主','','2013','約$1.53 billion','Museの調査: 同じくCrucible Moments Supercell回。「51%を買うが経営の実権は創業者に残す」と提案した経緯をPaananen本人が語っている。取引額はSoftBank発表を伝えた報道（2013年10月）で確認','https://podscan.fm/podcasts/crucible-moments/episodes/supercell-ft-ilkka-paananen-how-an-early-pivot-led-to-clash-of-clans-and-brawl-stars','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Tencent','Supercell','大株主','','2016','約$8.6 billion','Museの調査: 同じくCrucible Moments Supercell回でコンソーシアムによる取得が語られている（要約では評価額を取引額のように表現しているため注意）。裏付けはSoftBank公式発表（2016-06-21、SoftBank保有分の売却額は約$7.3 billion）と、取引総額約$8.6 bil','http://en.chinagate.cn/2016-06/21/content_38714401.htm','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Google','Wiz','買収','','2025','$32 billion','Museの調査: All-In Podcast 2025年3月21日回「White House BTS, Google buys Wiz, Treasury vs Fed, Space Rescue」で議論。なお2024年8月9日回では、WizがGoogleの$23 billionの買収提案を断った件も扱われている（不','https://blog.google/company-news/inside-google/company-announcements/google-agreement-acquire-wiz/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Microsoft','Activision Blizzard','買収','','2022','$68.7 billion','Museの調査: All-In Podcast E64（2022年1月22日）で、反トラスト基準の議論の中でこの買収が取り上げられたことを回の要約で確認。金額はMicrosoft公式発表（SEC提出資料）でも一致','https://www.sec.gov/Archives/edgar/data/718877/000110465922004746/tm223212d2_ex99-1.htm','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Meta Platforms','Scale AI','出資','','2025','約$14.3 billion','Museの調査: All-In Podcast 2025年6月20日回の文字起こしで出演者が「Meta invested over $14 billion in Scale AI for 49% stake」と発言。2025年8月の回でも振り返られている','https://www.reuters.com/business/finance/meta-finalizes-investment-scale-ai-valuing-startup-29-billion-2025-06-13/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Kleiner Perkins','Figma','資金調達','','2018','$25 million','Museの調査: 同じくTWIST E1040で「なぜKleiner Perkinsが投資したか」が語られている。金額・主導はFigma側の記録でも一致','https://www.clay.com/dossier/figma-funding','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Sequoia Capital','Figma','資金調達','','2019','$40 million','Museの調査: 同じくTWIST E1040で「SequoiaはSeries Bを見送ったが、後に（Series Cで）投資した」経緯が語られている。金額・主導はFigma側の記録でも一致','https://www.clay.com/dossier/figma-funding','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('ARK Invest','Manna','資金調達','','2026','$50 million','Museの調査: This Week in Startups「The Drone Company Quietly Taking Over Delivery」回（Manna創業者Bobby Healy出演）のタイムスタンプに調達の議論があり、番組ノートにもMannaの調達発表へのリンクがある。Wilson Sonsini','https://www.manna.aero/blog/series-b','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('TCV','Mercury','資金調達','','2026','$200 million','Museの調査: This Week in StartupsのMercury回（創業者Immad Akhund出演）で「なぜ黒字なのに$200 millionを調達するのか」が議論され、番組ノートにも同公式発表へのリンクがある','https://www.businesswire.com/news/home/20260520511817/en/Mercury-Raises-$200-Million-Series-D-at-$5.2B-Valuation','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Facebook, Inc.','Instagram','買収','','2012','approximately $1 billion','Museの調査: How I Built This第2回「Instagram: Kevin Systrom and Mike Krieger」（2016-09-19）で、創業者2人がFacebookへの売却の経緯を語る回。金額はFacebook公式発表と一致','https://about.fb.com/news/2012/04/facebook-to-acquire-instagram/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Amazon','Ring','買収','','2018','more than $1 billion','Museの調査: How I Built This「Ring: Jamie Siminoff」（2020-06-22）の回の説明に明記。裏付けはReuters（2018-02-27、TechCrunch経由で確認）','https://www.everand.com/podcast/466683975/Ring-Jamie-Siminoff','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Walmart','Bonobos','買収','','2017','$310 million','Museの調査: How I Built This「Bonobos: Andy Dunn」（2019-01-21）の回の説明に明記。金額はWalmart公式発表（2017-06-16）でも一致','https://www.npr.org/2019/01/18/686640146/bonobos-andy-dunn','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Kellogg Company','Chicago Bar Company','買収','','2017','$600 million','Museの調査: How I Built Thisライブ回「RXBAR: Peter Rahal」（2018-08-13）の説明に売却が明記（正式発表は10月）。Kellogg公式発表を伝えた報道でも確認','https://www.everand.com/podcast/417703526/Live-Episode-RXBAR-Peter-Rahal','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('TSG Consumer Partners','BrewDog','出資','','2017','£213 million','Museの調査: The Diary of a CEO E157 James Watt回（2022-07-04）で、2017年の£1 billion評価額とそれに伴うエピソードが語られている（回の要約で確認）。買い手名と金額は当時の報道で確認。なお公開されている文字起こしでは買い手名「TSG」自体の発言は確認できなかっ','https://www.episodenotes.com/episode-_5gfJdpgXvc-brewdog-founder-the-untold-story-of-one-britain-s-fastest-growin.html','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('eBay Inc.','Braintree','買収','','2013','$800 million','Museの調査: The Diary of a CEO Bryan Johnson回の文字起こしで、本人が「I sold Braintree Venmo… It sold for $800 million」と発言しているのを確認。金額はeBay公式発表（2013年、当時PayPalはeBay傘下）と一致','https://podscripts.co/podcasts/the-diary-of-a-ceo-with-steven-bartlett/the-man-thats-ageing-backwards-i-use-my-sons-blood-to-reverse-my-age-im-now-18-bryan-johnson','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('United States Steel Corporation','Carnegie Steel Company','買収','','1901','$480 million','Museの調査: Founders #283「Andrew Carnegie」回。ホストが「Andrew sells his steel company to J.P. Morgan for $480 million. J.P. Morgan combines that with U.S. Steel」と明言。買収主体','https://podscripts.co/podcasts/founders/283-andrew-carnegie','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Apple','NeXT','買収','','1996','総額 約$427 million','Museの調査: Founders「Steve Jobs in Exile」回の学習ノートに交渉場面が記録されている。総額はApple年次報告で確認','https://github.com/xrcodexcode/xr_node/blob/HEAD/02_NEW-KNOWLEDGE/steve-jobs-in-exile-study-note.md','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('McDonald''s Corporation','McDonald''s','買収','','1961','$2.7 million','Museの調査: Founders #293「The Making of McDonald''s」の文字起こしで「they were asking for $2.7 million」「to buy out the McDonald''s Brothers」と明言。原著の章題自体が「The $2.7 Million Hand','https://youtubetotranscript.com/transcript?v=E6OSZ8uRONA','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Blue Chip Stamps','See''s Candies','買収','','1972','$25 million','Museの調査: Founders #88「Shareholder Letters」／#100「The Snowball」などWarren Buffett回群。Buffettの株主レター自体が「We bought See''s for $25 million」と繰り返し明記。買収主体は当時Berkshire傘下のBlue','https://www.founders-library.com/f/warren-buffett','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('LVMH','Tiffany & Co.','買収','','2021','$15.8 billion','Museの調査: Founders #355「Rare Bernard Arnault Interview」の要約に買収が明記。Business Breakdowns EP.68でも同じ買収が取り上げられている。金額はLVMHの完了発表を伝えた報道で一致','https://podpulse.ai/podcast/founders/founders-355-rare-bernard-arnault-interview?ref=related-episode','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Berkshire Hathaway','Alleghany Corporation','買収','','2022','約$11.6 billion','Museの調査: Business Breakdowns EP.63「Berkshire Hathaway: The Incomparable Compounder」（2022-06-29）のショーノートに買収がケーススタディとして明記。金額はBerkshire Hathaway公式発表でも一致','https://pocketcasts.com/podcast/business-breakdowns/334745e0-6b62-0139-342a-0acc26574db2/berkshire-hathaway-the-incomparable-compounder/e62ba256-b962-47e1-a7e5-1b8932e03cb8','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Berkshire Hathaway','General Re Corporation','買収','','1998','約$22 billion','Museの調査: 同じくBusiness Breakdowns EP.63の文字起こしで買収が語られているのを確認。金額はBerkshire Hathawayの1998年公式発表で一致','https://pocketcasts.com/podcast/business-breakdowns/334745e0-6b62-0139-342a-0acc26574db2/berkshire-hathaway-the-incomparable-compounder/e62ba256-b962-47e1-a7e5-1b8932e03cb8','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('LVMH','Bulgari','買収','','2011','約€3.7 billion','Museの調査: Business Breakdowns EP.68「LVMH」の要約で買収が語られているのを確認。金額はReuters／Bloomberg報道とLVMH・Bulgari共同発表でも一致。FoundersのArnault回でも同買収に触れている','https://www.summarize.tech/www.youtube.com/watch?v=CMiqt7x0ZVY','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Salesforce','Tableau Software','買収','','2019','$15.7 billion','Museの調査: Business Breakdowns EP.29「Salesforce」のショーノートと文字起こしで、一連の買収が語られている（Tableauはその最大案件）。金額はSalesforceのSEC提出資料と公式発表で一致。なお同社のSlack買収は第3弾で収録済み','https://share.snipd.com/snip/8e2b177e-57c7-452c-94a2-a0fd03996fc1','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Procter & Gamble','Native','買収','','2017','$100 million','Museの調査: My First Million第10回（2019-08-28、創業者Moiz Ali出演）およびGreatest Hits #2（2021-05-10）で、本人が創業から2年半での売却経緯を語る回','https://www.myfirstmillion.org/episodes/greatest-hits-2-how-to-build-a-100-million-deodorant-business-starting-with-only-1000','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('HubSpot','The Hustle','買収','','2021','金額は公式発表では非公表','Museの調査: My First Million第153回「Selling The Hustle for Millions」（2021-02-12）で、共同ホストSam Parr本人が売却交渉の過程を語る回。買収にはMy First Million自体も含まれていた','https://www.martechcube.com/crm-leader-hubspot-signs-agreement-to-acquire-the-hustle/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('AOL','Bebo','買収','','2008','$850 million','Museの調査: My First Million第7回「The Hippie With A Billion Dollars」（創業者Michael Birch出演）で、本人がAOLへの売却と、その後の$1Mでの買い戻しを語る回。TechCrunchでも確認。なお買い戻しの買い手は個人のため行にしていない','https://www.openalmanac.org/w/founders-inc/my-first-million','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Twitch','Bebo','買収','','2019','最大$25 million','Museの調査: My First Million第108回（2020-09-07）で、共同ホストShaan Puri（当時BeboのCEO）が買い戻しとTwitchへの売却の経緯を詳しく語る回。買収自体はTwitch広報がTechCrunchに確認済み。同じBeboでも上記AOLの行とは別の取引','https://www.myfirstmillion.org/episodes/108-with-ben-gilbert-and-david-rosenthal-brainstorming-with-the-acquired-podcast','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Tiny Fund I LP','Letterboxd','買収','','2023','公式発表では取引条件非公表。後の報道では当時の会社評価額は$50–60 mill','Museの調査: My First Million「The 2023 Milly Awards: Part 2」（2023-12-18、Andrew Wilkinson出演）のクリップで本人が言及。取得はTiny Ltd.の公式ニュースリリースで確認。Wilkinson個人ではなくファンド（会社）が買い手のため対象にし','https://www.stockwatch.com/News/Item/Z-C!TINY-3461567/C/TINY','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Google','Nest Labs','買収','','2014','$3.2 billion','Museの調査: Masters of Scale Tony Fadell回の公式文字起こしで、ホストが「He sold Nest to Google for $3.2 billion」と明言。金額はGoogle公式発表（SEC提出資料）でも一致。第3弾のGoogleによるYouTube／Wiz買収とは別の取引','https://mastersofscale.com/wp-content/uploads/2022/08/masters-of-scale-episode-transcript_-tony-fadell.pdf','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Procter & Gamble','Walker & Company Brands','買収','','2018','金額未公表','Museの調査: Masters of Scale Tristan Walker回の文字起こしで買収が番組内で明言され、本人が調達で断られ続けた経緯と合わせて語る回。買収はP&Gの発表を伝えたTechCrunch（2018-12-12）でも確認','https://youtubetotranscript.com/transcript?v=qnV0407mO7A','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Roche','Flatiron Health','買収','','2018','$1.9 billion','Museの調査: The Logan Bartlett Show、Zach Weinberg出演回（EP54ほか）の説明文に「Flatiron Health, which sold to Roche for $1.9B」と明記。裏付けはRoche公式発表（2018-02-15）','https://theloganbartlettshow.simplecast.com/episodes/industry-episode-with-zach-weinberg-market-trends-avoiding-hiring-bullsers-and-who-will-win-in-ai-Y0Lif2a9','Muse調査(出典のページ)','');
