INSERT INTO money_flow VALUES ('Goldman Sachs','Industry Ventures','買収','','2025','$665 million','Museの調査: World of DaaS（現Summation）創業者Hans Swildens出演回で「Why Goldman Sachs paid almost $1 billion to acquire Industry Ventures」が議題として明記。金額の内訳はGoldman Sachs公式発表で確認','https://www.goldmansachs.com/pressroom/press-releases/2025/goldman-sachs-announces-acquisition-of-industry-ventures','Muse調査(出典のページ)','');
