INSERT INTO money_flow VALUES ('Oracle','BlueKai','買収','','2014','約$400 million','Museの調査: World of DaaS Omar Tawakol出演回の説明文に「acquired by Oracle for $400M+ in 2014」と明記（Tawakolが創業者）。TechCrunchも同様に報道','https://en.wikipedia.org/wiki/BlueKai','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Jane Street','MatX','資金調達','','2026','$500 million','Museの調査: Cheeky PintのMatX回（ゲストReiner Pope）。本人が文字起こしの中で「Series BはJane StreetとSituational Awarenessが主導、$500 million」と明言。MatX公式ブログ（2026-02-24）とTechCrunch同日報道でも確認。S','https://cheekypint.transistor.fm/25/transcript','Muse調査(出典のページ)','');
