INSERT INTO money_flow VALUES ('Cognition','Windsurf','買収','','2025','金額未公表','Museの調査: Cheeky PintのCognition回（ゲストScott Wu）はこの買収の経緯そのものが主題で詳しく語られているが、金額は番組内のどこにも出てこない。Big Technology Podcast（2025-07-18回）でも語られているため統合した。買収自体はCognition公式発表とTec','https://cheekypint.transistor.fm/8/transcript','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Y Combinator Continuity','Brex','資金調達','','2018','$50 million','Museの調査: Y Combinator公式ポッドキャスト第82回（ゲストHenrique Dubugras）。回の公式説明に「Series BはYC Continuityが主導」と明記され、回の中で調達の経緯が語られている。金額はBusiness Wireの公式発表、WSJ、TechCrunchで確認。YC Con','https://www.podchaser.com/podcasts/y-combinator-startup-podcast-526094/episodes/82-henrique-dubugras-of-brex-a-29430217','Muse調査(出典のページ)','');
