INSERT INTO money_flow VALUES ('Accel Partners','Atlassian','出資','','2010','$60 million','Museの調査: Decoderの前身番組Recode DecodeのMike Cannon-Brookes回（同じ配信フィードに収録）で、本人が「2010年にAccelから約$60 millionのセカンダリーラウンドを受けた」と発言。金額はAtlassian公式発表（2010-07-14）でも一致','https://www.atlassian.com/blog/news/2010/07/atlassian_closes_60_million_investment_from_accel_partners','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Canva','Serif','買収','','2024','金額未公表','Museの調査: Decoder 2024年7月回（Canva CEO Melanie Perkins出演）で、Affinity買収がAdobeへの対抗策として本人により語られたことを、回の内容を伝えたPetaPixel記事で確認。買収自体はCanva公式発表（2024-03-26）でも確認','https://petapixel.com/2024/07/08/canva-ceo-adobe-has-been-in-a-one-horse-race-for-too-long/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('ICONIQ Capital','Anthropic','資金調達','','2025','$13 billion','Museの調査: Big Technology Podcast 2025年9月5日回の文字起こしで「Anthropic has raised a 13 billion series F at a post-money valuation of $183 billion」と明言。主導と金額はAnthropic公式発表でも','https://podscripts.co/podcasts/big-technology-podcast/googles-best-week-ever-ais-rising-costs-putin-and-xis-immortality-quest','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('OpenAI','io Products','買収','','2025','約$6.5 billion','Museの調査: Big Technology Podcast「OpenAI''s Jony Ive Moment…」回（2025年5月）の項目に買収が明記。買収はOpenAI公式発表でも確認され、金額はBloomberg等の報道で一致','https://podbay.fm/p/big-technology-podcast/e/1748045640','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Google','Windsurf','買収','','2025','$2.4 billion','Museの調査: Big Technology Podcast 2025年7月18日回の文字起こしで「Google has paid $2.4 billion to bring on some of the top leadership of windsurf」と明言。ただし会社自体の買収ではなく、技術ライセンスとCE','https://podscripts.co/podcasts/big-technology-podcast/groks-ai-lovebot-aqui-hire-sition-backlash-openais-chatgpt-agent-debuts','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Skydance Media','Paramount Global','買収','','2024','$8 billion','Museの調査: Pivot 2024年7月9日回の文字起こしで金額が明言されている。完了はParamount Skydance公式発表（2025-08-07）でも確認','https://podscripts.co/podcasts/pivot/bidens-future-paramount-skydance-merger-and-guest-brian-derrick','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Paramount Skydance','Warner Bros. Discovery','買収','','2026','企業価値 約$110 billion','Museの調査: Pivot回の文字起こしで「Paramount has officially completed its $81 billion acquisition of Warner Bros. Discovery」と明言。完了はSkydance公式発表（2026-10-06）でも確認。なお先行したNetfli','https://podcasts.happyscribe.com/pivot/camp-donald-bezos-s-ai-fantasy-and-desperately-seeking-kara-swisher','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('xAI','X','買収','','2025','$33 billion','Museの調査: Pivot回（2025年4月）の文字起こしで「Elon Musk''s X has been acquired by Elon Musk''s xAI」と議論。金額はxAI公式発表で確認。両社とも同じオーナー傘下の取引である点に注意','https://podscripts.co/podcasts/pivot/elon-merges-companies-whca-cuts-comedian-and-guest-co-host-jen-psaki','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Disc Makers','CD Baby','買収','','2008','$22 million','Museの調査: The Tim Ferriss Show #202「Derek Sivers Distilled」の公式文字起こしで、ホスト自身の紹介として「In 2008, Derek sold CD Baby for $22 million」と明記。買い手がDisc MakersであることはFerriss本人のブ','https://tim.blog/2018/06/20/the-tim-ferriss-show-transcripts-derek-sivers-distilled/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Bain Capital','TOMS','出資','','2014','約$313 million','Museの調査: The Tim Ferriss ShowのBlake Mycoskie出演回（#446ほか）で「会社の半分を売却した」ことが主題。持分取得と評価額はReuters報道を引く複数資料で一致。本人は残り50%を保持し創業者として残った','http://tim.blog/2021/12/05/blake-mycoskie-3-transcript/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Greatbatch, Inc.','NanoGram Devices Corporation','買収','','2004','$50 million','Museの調査: SaaStr Podcast #090／#091（ホストJason Lemkin自身がゲストの回）の番組紹介文に「NanoGram Devices, which was acquired for $50m just 13 months after founding」と明記され、Lemkin本人が共同創','https://www.saastr.com/saastr-podcast-091-jason-lemkin-founder-vc-saastr-on-why-founders-must-be-110-committed-to-sales/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Astera Institute','Imbue','資金調達','','2023','$200 million','Museの調査: No PriorsのImbue回（共同創業者出演）の説明に調達が回の主題として明記。主導と金額はTechCrunch（2023-09-07）でも確認。NVIDIAほかが参加','https://podbay.fm/p/no-priors-artificial-intelligence-or-technology-or-startups/e/1700138391','Muse調査(出典のページ)','');
