INSERT INTO money_flow VALUES ('Sequence Holdings','The Baldwin Group','買収','','2026','約$7.7 billion','Museの調査: No Priors「Re-Founding Incumbents for the AI Era」回（Sequence Holdings CEO Michael Lee出演、2026-09-24公開）で、この買収が語られている。買い手はSequenceとDFO Managementが共同で組成する主体で','https://www.youtube.com/watch?v=TCpRwJBQvW0','Muse調査(出典のページ)','');
