INSERT INTO money_flow VALUES ('General Catalyst','Adept','資金調達','','2023','$350 million','Museの調査: Latent SpaceのDavid Luan回（Adept CEO）の文字起こしで、ホストが調達額を本人に確認している。共同主導と金額はTechCrunch（2023-03-15）でも一致。Addition、Greylock、Microsoft、NVIDIA等が参加','https://lawwu.github.io/transcripts/transcript_wmPPiW4K_es.html','Muse調査(出典のページ)','');
