INSERT INTO money_flow VALUES ('Paradigm','Nous Research','資金調達','','2025','$50 million','Museの調査: Latent SpaceのNous Research回（共同創業者出演、2025年4月）をもとにした番組側の会社プロフィールに資金調達が明記。金額はFortune（2025-04-25）とSiliconANGLEでも一致','https://latent.space/wiki/nous-research-dbe71fb5/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Meritech Capital Partners','fal','資金調達','','2025','$125 million','Museの調査: Latent Spaceのfal回（共同創業者出演、2025-09-08公開）の要約に調達が明記。主導と金額は同社のBusiness Wire発表でも一致。Salesforce Ventures、Shopify Ventures、Google AI Futures Fund、Bessemer等が参加','https://latentspace.podhood.com/products/stable-diffusion','Muse調査(出典のページ)','');
