INSERT INTO money_flow VALUES ('AT&T','Time Warner','買収','','2016','$85.4 billion','Museの調査: Rubenstein Show、Randall Stephenson（AT&T CEO）出演回。ホストが回の中で買収額を明言し、政府との訴訟も含め買収が主題。金額はAT&T公式発表（SEC提出資料）でも一致','https://archive.org/details/BLOOMBERG_20190502_010000_The_David_Rubenstein_Show_Peer_to_Peer_Conversations','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Banco Santander','Webster Financial','買収','','2026','$12.2 billion','Museの調査: Rubenstein Show、Ana Botín（Santander会長）出演回。ホストが買収額を発言し、回のナレーションでも明言。金額・完了はSantander公式発表でも一致','https://archive.org/details/BLOOMBERG_20261018_170000_The_David_Rubenstein_Show_Peer_to_Peer_Conversations','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Blackstone','Hilton Hotels','買収','','2007','$26 billion','Museの調査: Rubenstein Show、Stephen Schwarzman出演回でHilton買収と売却益が語られている。Chris Nassetta（Hilton CEO）出演回（2021年12月）でも経緯と金額への言及あり。金額$26 billionは当時の報道で一致','https://archive.org/details/BLOOMBERG_20191124_193000_The_David_Rubenstein_Show_Peer_to_Peer_Conversations','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Blackstone','Equity Office Properties','買収','','2007','約$39 billion','Museの調査: Rubenstein Show、Stephen Schwarzman出演回で本人が「just buying $39 billion of real estate」と発言。総額$39 billionはProperty Week（2007年2月）等の報道でも一致','https://archive.org/details/BLOOMBERG_20191130_180000_The_David_Rubenstein_Show_Peer_to_Peer_Conversations','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Yahoo','Broadcast.com','買収','','1999','$5.7 billion','Museの調査: Masters in Business、Mark Cuban出演回の文字起こしで売却が中心に語られている。金額はYahoo公式発表を伝えた当時のWSJ報道等でも一致。なお同じ回で語られるCuban本人によるDallas Mavericksの購入は、買い手が個人のため行にしていない','https://share.snipd.com/chapter/61656a89-1bbd-4590-9cc7-c1b27d838fb1','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('LPL Financial','Commonwealth Financial Network','買収','','2025','約$2.7 billion','Museの調査: Masters in Business、Rich Steinmeier（LPL Financial CEO）出演回（2026年10月公開）の説明に買収が明記され、買収が語られている。金額・完了はLPLの公式発表と2025年10-Kでも一致','https://www.tapesearch.com/podcast/masters-in-business/730188152','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('BlackRock','Barclays Global Investors','買収','','2009','$13.5 billion','Museの調査: Masters in Business、Mike Pyle（BlackRock）出演回の公式文字起こしで、ホストがこの買収で入ってきた事業であることを明言。ただし買収金額自体は番組内では発言されておらず、行の金額はBarclaysの公式発表（SEC提出資料）で確認したもの','https://ritholtz.com/2026/04/transcript-mike-pyle/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Amazon','Whole Foods Market','買収','','2017','$13.7 billion','Museの調査: How Leaders Lead #205 John Mackey回（共同創業者本人出演）で買収が語られ、Rubenstein ShowのMackey回でも売却の経緯が詳しく語られているため統合した（Rubenstein回では金額自体は発言されていない）。金額はAmazon公式発表と一致','https://press.aboutamazon.com/2017/6/amazon-to-acquire-whole-foods-market','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('JPMorgan Chase','Bear Stearns','買収','','2008','約$1.2 billion','Museの調査: How Leaders Lead EP224 Jamie Dimon回。金融危機下の買収交渉をDimon本人が語る回。金額の引き上げ経緯はNPR等の当時報道でも一致','https://www.mtpr.org/2008-03-24/jpmorgan-boosts-offer-for-bear-stearns-buyout?_amp=true','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('The Carlyle Group','Beautycounter','大株主','','2021','取引評価額 $1 billion','Museの調査: How Leaders Lead #268 Gregg Renfrew回（創業者本人出演）。回の説明に「10億ドル評価額で売却し、その後買い戻した」経緯が明記。過半数取得と評価額は2021-04-13の公式発表（PR Newswire）と一致。なお2024年の買い戻しの買い手はRenfrew側のため行','https://www.nasdaq.com/press-release/beautycounter-the-industry-leading-clean-beauty-brand-partners-with-the-carlyle-group','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('The Simply Good Foods Company','Quest Nutrition','買収','','2019','$1.0 billion','Museの調査: How Leaders Lead #297 Dave Ritterbush回（Questの元CEO）。回の説明に「Quest, which sold for a billion dollars in 2019」と明記。金額はSimply Good Foods公式発表とSEC提出の完了リリースでも一致','https://www.globenewswire.com/news-release/2019/08/21/1905113/0/en/The-Simply-Good-Foods-Company-to-Acquire-Quest-Nutrition.html','Muse調査(出典のページ)','');
