INSERT INTO money_flow VALUES ('eBay','Half.com','買収','','2000','約$350 million','Museの調査: Invested by Aleph Josh Kopelman回（Half.com創業者本人出演）。回の説明に売却が明記され、ドットコム期の売却が語られている。金額はTechCrunch等の報道で確認','https://techcrunch.com/2010/08/16/ebays-new-iphone-app-helps-students-compare-buy-textbooks-on-half-com/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Mars, Incorporated','KIND','買収','','2020','評価額 約$5 billion','Museの調査: Invested by Aleph Episode 76 Daniel Lubetzky回（KIND創業者本人出演）。チャプターに売却の章があり、売却が語られている。ただし番組タイトルは「$7 Billion Valuation」と表現しており、2020年のMars取引について報道された約$5 bil','https://www.fooddive.com/news/mars-buys-kind-north-america/589209/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('3G Capital','Burger King Holdings','買収','','2010','株式価値$3.26 billion','Museの調査: Capital Allocators「Private Equity Deals」S3.EP.09「Classic Deal - Burger King by 3G Capital」（2024-05-06公開、出演者あり）で買収の経緯が主題。金額はReuters等の当時報道と一致','https://www.nrn.com/mergers-acquisitions/3g-completes-burger-king-acquisition','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Thoma Bravo','RealPage','買収','','2021','約$10.2 billion','Museの調査: Capital Allocators「Private Equity Deals」EP.2「Thoma Bravo, Scott Crabill – Public-to-Private at RealPage」（2022-09-28公開）。回の説明に買収額と「当時同社最大の取引」が明記。金額はRealP','https://www.businesswire.com/news/home/20210422005682/en/','Muse調査(出典のページ)','');
