INSERT INTO money_flow VALUES ('Occidental Petroleum','CrownRock, L.P.','買収','','2024','発表時 約$12.0 billion','Museの調査: Capital Allocators「Private Equity Deals」S3.EP.11「Striking Oil – CrownRock by Lime Rock Capital」（2025-01-20公開）。CrownRockはLime Rock PartnersとCrownQuest O','https://occidentalpetroleum.gcs-web.com/static-files/7025e1a9-5425-43bb-8d4e-fd4e31e63938','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Nucor Corporation','C.H.I. Overhead Doors','買収','','2022','$3.0 billion','Museの調査: Capital AllocatorsのKKR Pete Stavros回で、KKRによる2015年の買収から経営改善、Nucorへの売却（イグジット）までが語られている。金額はNucorの公式完了発表と一致。なおKKRの2015年の買収額は公式未公表のため行にしていない','https://nucor.com/news/?article=nucor-completes-acquisition-of-chi-overhead-doors-122921','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Silver Lake Partners','Dell Inc.','買収','','2013','$24.9 billion','Museの調査: We Study Billionaires（TIP）のDell企業分析回で非公開化が語られている（公式解説ページ https://www.theinvestorspodcast.com/intrinsic-value/dell-dell/ ）。金額はDellの公式完了発表と一致','https://siliconangle.com/2013/10/31/dell-now-officially-private/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Dell','EMC Corporation','買収','','2016','約$67 billion','Museの調査: 同じくWe Study Billionaires（TIP）のDell企業分析回で「$67 billionのEMC買収」が同社の転機として語られている。金額・完了日はDellの公式発表を伝えたBloomberg報道でも一致。第4弾のBroadcom→VMwareとは別の取引','https://www.businesstimes.com.sg/startups-tech/technology/dell-emc-complete-largest-tech-deal-company-looks-invest','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('The Estée Lauder Companies','TOM FORD','買収','','2023','企業価値$2.8 billion','Museの調査: We Study Billionaires（TIP）のEstée Lauder企業分析回で「同社最大の買収」として語られている（公式解説ページ https://www.theinvestorspodcast.com/intrinsic-value/estee-lauder-el/ ）。金額はELCの公','https://www.businesswire.com/news/home/20230428005308/en/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Crocs, Inc.','HEYDUDE','買収','','2022','発表時$2.5 billion','Museの調査: We Study Billionaires（TIP）のCrocs企業分析回に買収の節があり、買収とその後の苦戦が語られている（公式解説ページ https://www.theinvestorspodcast.com/intrinsic-value/crocs-crox/ ）。金額はCrocsの公式完了発','https://expertini.com/prnews/article/crocs-inc-completes-acquisition-of-casual-footwear-brand-heydude-tm--2022-02-17/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Merck','Prometheus Biosciences','買収','','2023','$10.8 billion','Museの調査: Talks at GSのMark McKenna回（Mirador Therapeutics創業者、2024年10月17日収録）の文字起こしで、司会が買収額を明言し、McKenna本人も売却の経緯を語っている。金額はMerck公式発表（SEC提出のプレスリリース）と一致。回の文字起こしは https:','https://www.sec.gov/Archives/edgar/data/1718852/000119312523102770/d462383dex991.htm','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('TPG Inc.','Angelo Gordon','買収','','2023','$2.7 billion','Museの調査: Talks at GSのJon Winkelried回（TPG CEO、2026年6月9日収録）の文字起こし冒頭で買収が同社の節目として明示され、対談でも触れられている。$2.7 billionは発表時の評価額としてFT等が報道。回の文字起こしは https://www.goldmansachs.co','https://en.wikipedia.org/wiki/Angelo_Gordon','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Royal Bank of Scotland','Bibit','買収','','2004','$100 million','Museの調査: Talks at GSのPieter van der Does回（Adyen共同創業者、2025年11月5日収録）の文字起こしで、司会が買収を明言し、本人も売却の理由を語っている。金額$100 millionはReuters（2024年）で確認。回の文字起こしは https://www.goldman','https://es.tradingview.com/news/reuters.com%2C2024%3Anewsml_L8N3LQ1AJ%3A0-adyen-co-founder-s-new-firm-tebi-raises-22-mln-to-expand/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Samsung Electronics','Mistral AI','資金調達','','2026','€3 billion','Museの調査: Sifted Podcast「Is Mistral''s monster fundraise a win for European sovereignty?」回（2026年9月11日）の説明自体に金額・評価額・主導が明記され、回の主題として語られている。金額・主導はBloomberg・EU-Startu','https://www.eneralabs.com/blog/mistral-3b-samsung-nvidia-enterprise-2026/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('ASML','Mistral AI','資金調達','','2025','€1.7 billion','Museの調査: 同じく上記のSifted Podcast Mistral回の説明で前年ラウンドの評価額に言及されており、その調達がASML主導のSeries CであることはMistral発表を伝えたBloomberg等の報道で確認。取り込み時は、回で直接語られたのはSeries Dが中心で、Series Cは評価額へ','https://www.eneralabs.com/blog/mistral-3b-samsung-nvidia-enterprise-2026/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Candle Media','Hello Sunshine','買収','','2021','評価額 約$900 million','Museの調査: The Circuit、Reese Witherspoon回（創業者本人出演）。番組冒頭のナレーションで金額が明言されている（回の文字起こし https://youtubetotranscript.com/transcript?v=SPWTLzHpV5Y で確認）。金額・過半数取得はBloomberg','https://themalaysianreserve.com/2025/12/19/why-reese-witherspoon-is-now-a-bigger-deal-than-oprah/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Facebook','Oculus VR','買収','','2014','約$2 billion','Museの調査: The Circuit、Palmer Luckey回（Oculus創業者本人出演、2024年5月）。OculusをFacebookに売却した経緯と、その後の解雇が回の主題として語られている。金額はFacebook公式発表を伝えた各社報道でも一致','https://stockpick.market/2024/06/23/who-is-palmer-luckey-the-founder-of-oculus-and-anduril/','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('USA Waste Services','United Waste Systems','買収','','1997','約$2.5 billion','Museの調査: Odd Lots、Brad Jacobs回。ホストの紹介で売却が明言されている。買い手の正式名称はUSA Waste Services（後にWaste Managementとなる会社）で、金額・年はBarron''s等の報道でも一致。第4弾のFounders Podcast側のJacobs回とは別の回か','https://www.barrons.com/articles/ckx-lands-stock-brad-jacobs-united-rentals-63dc9f64','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Ludlow Ventures','Stir','資金調達','','2020','$4 million','Museの調査: 裏付け直しで確定。番組で不明だった「主導か参加か」も共同主導と判明。個人のエンジェル参加者は出資側に入れていない','https://every.to/means-of-creation/building-the-best-tools-for-creators-15398883','Muse調査(出典のページ)','');
INSERT INTO money_flow VALUES ('Index Ventures','Fast','資金調達','','2019','$2.5 million','Museの調査: 裏付け直しで確定。金額と時期は会社の公式発表（Series B発表の中にプレシードの明記あり）で確認。Index主導はTechCrunch報道でも確認。なお海外バッチ第7弾の「Stripe→Fast（2021年 Series B）」とは別のラウンド','https://www.prnewswire.com/news-releases/fast-announces-102-million-in-series-b-funding-fueling-rapid-adoption-of-one-click-checkout-across-the-internet-301215036.html','Muse調査(出典のページ)','');
