INSERT INTO money_flow VALUES ('Khosla Ventures','Eight Sleep','資金調達','','2018','$14 million','Museの調査: 裏付け直しで、行にできるラウンドが特定できた。ただしKhoslaは2019年のラウンドと2021年のSeries Cにも参加しており（いずれも主導は別ファンド）、番組の発言がどのラウンドを指していたかまでは特定できない','https://www.gaebler.com/VC-Funding-2D679AFA-8F77-4233-B9B3-CD24B1530E26-Eight-Sleep-03-09-2018','Muse調査(出典のページ)','');
