INSERT INTO money_flow VALUES ('Lime Rock Partners','CrownRock, L.P.','出資','','2007','$96.5 million','Museの調査: 裏付け直しで確定（WSJ記事の転載で確認）。注意点：WSJの言い方は「組成以来投じた累計」に近く、番組説明の「2007年に現金・資産$96.5 millionで作った」と完全に同じ意味かは断定できない（第7弾Bからの格上げ）','https://origin-pre-prod.livemint.com/companies/news/this-little-known-private-equity-firm-booked-a-79-fold-return-11729679850645.html','Muse調査(出典のページ)','');
